CREATE OR REPLACE FUNCTION public.sales_quote_auto_installed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  total_paid numeric;
BEGIN
  -- Skip if not in received state, or status is being changed away from received
  IF NEW.status IS DISTINCT FROM 'received' THEN
    RETURN NEW;
  END IF;

  -- Only act when we have a real total to compare against
  IF NEW.total_amount IS NULL OR NEW.total_amount <= 0 THEN
    RETURN NEW;
  END IF;

  -- Scope: 805 Shutters + MTS Installations only
  IF NEW.account_id NOT IN (
    '72ccf12a-11c0-4261-8ad0-31af8ad0bbfb',
    'a1b2c3d4-e5f6-7890-abcd-ef1234567890'
  ) THEN
    RETURN NEW;
  END IF;

  total_paid := COALESCE(NEW.deposit_paid, 0) + COALESCE(NEW.balance_paid, 0);

  -- Fully paid (within 1 cent tolerance) → advance
  IF total_paid >= NEW.total_amount - 0.01 THEN
    NEW.status := 'installed';
    NEW.installed_at := now();
    RAISE NOTICE 'sales_quote_auto_installed: % advanced received→installed (paid=%, total=%)',
      NEW.id, total_paid, NEW.total_amount;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_sales_805_appointments_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
